window.ox.install(({action})=>{action("searchRates",{async invoke(args){const until=Date.now()+25000;while(Date.now()<until){if(/Show us your human side/.test(document.body.innerText))throw Error("Hotels.com human verification required");const cards=[...document.querySelectorAll('[data-stid="lodging-card-responsive"]')];if(cards.some(e=>/Grand Hyatt Kauai/.test(e.innerText)&&/total/.test(e.innerText))){const u=new URL(location.href);if(u.searchParams.get("startDate")!==args.checkIn||u.searchParams.get("endDate")!==args.checkOut||u.searchParams.get("adults")!==args.adults)throw Error("Search date or occupancy mismatch");return {items:cards.slice(0,5).map(e=>({text:e.innerText})),nextCursor:null,url:location.href};}await new Promise(r=>setTimeout(r,250));}throw Error("Hotel rates did not load");}});});